import React from 'react';

import { IWorkoutFull } from '@apps/Workouts/@types/workouts.types';
import { IWorkoutTrackMarkup } from '@apps/Workouts/@types/workoutTrackMarkup.types';
import { formatDistance } from '@helpers/formatHelper';
import { getDistanceByCoordsInMeters } from '@helpers/gpsHelper';
import { round } from '@helpers/mathHelper';

interface IWorkoutTrackMarkupTableProps {
  workout: Pick<IWorkoutFull, 'track'>;
  markups: IWorkoutTrackMarkup[];
}

const WorkoutTrackMarkupTable: React.FC<IWorkoutTrackMarkupTableProps> = ({ workout, markups }) => {
  let lastOrph = 0;
  let usedInBreak = false;

  const sums = {
    duration: 0,
    durationBreaks: 0,
    distance: 0,
    maxAlti: 0,
    minAlti: 99999999,
  };

  const data = workout.track.reduce<
    Record<number, Partial<IWorkoutTrackMarkup> & { sor: number; points: IWorkoutFull['track'] }>
  >((acc, val, index) => {
    const time = val.date.getTime();
    usedInBreak = false;

    markups.forEach((markup) => {
      if (time >= markup.utcD1.getTime() && time <= markup.utcD2.getTime()) {
        if (!acc[markup.id]) {
          acc[markup.id] = {
            ...markup,
            sor: markup.utcD1.getTime(),
            points: [],
          };
        }

        acc[markup.id].points.push(val);
        if (!usedInBreak) {
          usedInBreak = true;
        }
      }
    });

    if (!usedInBreak) {
      if (!acc[lastOrph]) {
        acc[lastOrph] = {
          sor: val.date.getTime(),
          points: [],
        };
      }

      acc[lastOrph].points.push(val);
    } else {
      lastOrph = index * -1;
    }

    return acc;
  }, {});

  return (
    <table className="table table-sm table-bordered table-striped">
      <thead>
        <tr>
          <th rowSpan={2}>№</th>
          <th rowSpan={2}>Начало</th>
          <th rowSpan={2}>Конец</th>
          <th rowSpan={2}>Продолж.</th>
          <th rowSpan={2}>Расст-е</th>
          <th rowSpan={2}>Скорость</th>
          <th colSpan={3}>Высота</th>
        </tr>
        <tr>
          <th>max</th>
          <th>min</th>
          <th>перепад</th>
        </tr>
      </thead>
      <tbody>
        {Object.values(data)
          .sort((a, b) => (a.sor > b.sor ? 1 : a.sor < b.sor ? -1 : 0))
          .map((x, i) => {
            const d1 = x.points[0].date;
            const d2 = x.points[x.points.length - 1].date;
            const dist = getDistanceByCoordsInMeters(
              x.points.map((a) => a.point).map(([a, b]) => [a, b]),
            );
            const minAlti = Math.min(
              ...x.points.map((a) => +(a.point as [number, number, number])[2]),
            );
            const maxAlti = Math.max(
              ...x.points.map((a) => +(a.point as [number, number, number])[2]),
            );

            sums.distance += dist;
            sums.maxAlti = maxAlti > sums.maxAlti ? maxAlti : sums.maxAlti;
            sums.minAlti = minAlti < sums.minAlti ? minAlti : sums.minAlti;
            sums.duration += x.name ? 0 : d2.getTime() - d1.getTime();
            sums.durationBreaks += x.name ? d2.getTime() - d1.getTime() : 0;

            return (
              <tr key={x.sor}>
                <td className="text-end">{i + 1}</td>
                <td className="text-end">{d1.toLocaleTimeString()}</td>
                <td className="text-end">{d2.toLocaleTimeString()}</td>
                <td className="text-end">
                  {new Date(
                    d2.getTime() - d1.getTime() + new Date().getTimezoneOffset() * 60 * 1000,
                  ).toLocaleTimeString()}
                </td>
                {x.name ? (
                  <td colSpan={5} className="text-end">
                    <small>привал: {x.name}</small>
                  </td>
                ) : (
                  <>
                    <td className="text-end">{formatDistance(dist)}</td>
                    {}
                    <td className="text-end">
                      {round((dist / 1000 / (d2.getTime() - d1.getTime())) * 1000 * 60 * 60, 1)}
                      &thinsp;км/ч
                    </td>
                    <td className="text-end">{round(maxAlti, 0)}</td>
                    <td className="text-end">{round(minAlti, 0)}</td>
                    <td className="text-end">{round(maxAlti - minAlti, 0)}</td>
                  </>
                )}
              </tr>
            );
          })}
      </tbody>
      <tfoot>
        <tr>
          <th className="text-end" rowSpan={2} colSpan={2}>
            Итого
          </th>
          <th>Привалы</th>
          <th className="text-end">
            {new Date(
              sums.durationBreaks + new Date().getTimezoneOffset() * 60 * 1000,
            ).toLocaleTimeString()}
          </th>
          <th className="text-end" colSpan={5}>
            -
          </th>
        </tr>
        <tr>
          <th>Движ-е</th>
          <th className="text-end">
            {new Date(
              sums.duration + new Date().getTimezoneOffset() * 60 * 1000,
            ).toLocaleTimeString()}
          </th>
          <th className="text-end">{formatDistance(sums.distance)}</th>
          {}
          <th className="text-end">
            {round((sums.distance / 1000 / sums.duration) * 1000 * 60 * 60, 1)}&thinsp;км/ч
          </th>
          <th className="text-end">{round(sums.maxAlti, 0)}</th>
          <th className="text-end">{round(sums.minAlti, 0)}</th>
          <th className="text-end">{round(sums.maxAlti - sums.minAlti)}</th>
        </tr>
      </tfoot>
    </table>
  );
};

export default WorkoutTrackMarkupTable;
